import XCTest
import MetalKit
import UIKit
import simd
@testable import VROS

/// An attachment generated by the production shaders/meshes, not a design mockup.
@MainActor
final class SpatialHomeCaptureTests: XCTestCase {
    func testCaptureActualStereoHomeBeforeLensCorrection() throws {
        guard let device = MTLCreateSystemDefaultDevice() else { throw XCTSkip("Metal indisponível") }
        let library = try device.makeDefaultLibrary(bundle: Bundle(for: VRRenderer.self))
        let ui = try SpatialUIRenderer(device: device, library: library, pixelFormat: .bgra8Unorm)
        var workspace = SpatialWorkspace()
        workspace.perform(.setDistance(2.3), headPose: simd_quatf(real: 1, imag: .zero), at: 0)
        workspace.update(at: 1)
        workspace.setSystemSummary(time: "10:42", date: "sábado, 31 de outubro",
                                   status: "3DoF • Mira da cabeça", battery: "iPhone • captura de teste")
        let ray = SpatialRay(origin: StereoCamera.headPosition, direction: SIMD3(0, 0, -1))
        let hit = try XCTUnwrap(SpatialGeometry.intersect(ray: ray, windows: workspace.windows))
        ui.prepare(SpatialRenderFrame(windows: workspace.windows, focusedElementID: nil, grabbedWindowID: nil,
                                      pointer: SpatialPointerVisual(ray: ray, end: hit.point, isLaser: false,
                                                                    isHit: true, dwellProgress: 0, selectionPulse: 0), time: 1))
        let vertices = HomeEnvironment.vertices()
        let buffer = try XCTUnwrap(vertices.withUnsafeBufferPointer {
            device.makeBuffer(bytes: $0.baseAddress!, length: $0.count * MemoryLayout<SceneVertex>.stride,
                              options: .storageModeShared)
        })
        let pipelineDescriptor = MTLRenderPipelineDescriptor()
        pipelineDescriptor.vertexFunction = library.makeFunction(name: "sceneVertex")
        pipelineDescriptor.fragmentFunction = library.makeFunction(name: "sceneFragment")
        pipelineDescriptor.colorAttachments[0].pixelFormat = .bgra8Unorm
        pipelineDescriptor.depthAttachmentPixelFormat = .depth32Float
        let pipeline = try device.makeRenderPipelineState(descriptor: pipelineDescriptor)
        let depthDescriptor = MTLDepthStencilDescriptor()
        depthDescriptor.depthCompareFunction = .less
        depthDescriptor.isDepthWriteEnabled = true
        let depthState = try XCTUnwrap(device.makeDepthStencilState(descriptor: depthDescriptor))
        let width = 1280, height = 590
        let colorDescriptor = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: .bgra8Unorm,
                                                                      width: width, height: height, mipmapped: false)
        colorDescriptor.storageMode = .shared
        colorDescriptor.usage = .renderTarget
        let color = try XCTUnwrap(device.makeTexture(descriptor: colorDescriptor))
        let depthTextureDescriptor = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: .depth32Float,
                                                                             width: width, height: height, mipmapped: false)
        depthTextureDescriptor.storageMode = .private
        depthTextureDescriptor.usage = .renderTarget
        let depth = try XCTUnwrap(device.makeTexture(descriptor: depthTextureDescriptor))
        let pass = MTLRenderPassDescriptor()
        pass.colorAttachments[0].texture = color
        pass.colorAttachments[0].loadAction = .clear
        pass.colorAttachments[0].storeAction = .store
        pass.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 1)
        pass.depthAttachment.texture = depth
        pass.depthAttachment.loadAction = .clear
        pass.depthAttachment.storeAction = .dontCare
        pass.depthAttachment.clearDepth = 1
        let queue = try XCTUnwrap(device.makeCommandQueue())
        let command = try XCTUnwrap(queue.makeCommandBuffer())
        let encoder = try XCTUnwrap(command.makeRenderCommandEncoder(descriptor: pass))
        for eye in StereoCamera.Eye.allCases {
            let range = StereoCamera.horizontalRange(eye, drawableWidth: width)
            encoder.setViewport(MTLViewport(originX: Double(range.lowerBound), originY: 0,
                                            width: Double(range.count), height: Double(height), znear: 0, zfar: 1))
            encoder.setScissorRect(MTLScissorRect(x: range.lowerBound, y: 0, width: range.count, height: height))
            let projection = StereoCamera.projection(verticalFOVDegrees: 90,
                                                     aspect: Float(range.count) / Float(height), centerX: 0.5)
            var matrix = projection * StereoCamera.viewMatrix(eye, orientation: simd_quatf(real: 1, imag: .zero), ipdMeters: 0.064)
            encoder.setRenderPipelineState(pipeline)
            encoder.setDepthStencilState(depthState)
            encoder.setCullMode(.none)
            encoder.setVertexBuffer(buffer, offset: 0, index: 0)
            encoder.setVertexBytes(&matrix, length: MemoryLayout<simd_float4x4>.stride, index: 1)
            encoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: vertices.count)
            ui.encode(encoder: encoder, viewProjection: matrix)
        }
        encoder.endEncoding()
        command.commit(); command.waitUntilCompleted()
        XCTAssertEqual(command.status, .completed, "\(String(describing: command.error))")
        var pixels = [UInt8](repeating: 0, count: width * height * 4)
        pixels.withUnsafeMutableBytes {
            color.getBytes($0.baseAddress!, bytesPerRow: width * 4,
                           from: MTLRegionMake2D(0, 0, width, height), mipmapLevel: 0)
        }
        let provider = try XCTUnwrap(CGDataProvider(data: Data(pixels) as CFData))
        let bitmapInfo = CGBitmapInfo(rawValue: CGImageAlphaInfo.premultipliedFirst.rawValue |
                                               CGBitmapInfo.byteOrder32Little.rawValue)
        let image = try XCTUnwrap(CGImage(width: width, height: height, bitsPerComponent: 8, bitsPerPixel: 32,
                                         bytesPerRow: width * 4, space: CGColorSpaceCreateDeviceRGB(),
                                         bitmapInfo: bitmapInfo, provider: provider, decode: nil,
                                         shouldInterpolate: false, intent: .defaultIntent))
        let attachment = XCTAttachment(image: UIImage(cgImage: image))
        attachment.name = "Actual-Metal-Home-SBS-before-optics"
        attachment.lifetime = .keepAlways
        add(attachment)
    }
}
